export const LEVEL_DRAG=Object.freeze({threshold:7,friction:7,velocityFilter:18,maxSpeed:2400,stopSpeed:6});
const clamp=(n,min,max)=>Math.max(min,Math.min(max,n));
export class LevelDragMotion{
  constructor(){this.position=0;this.maximum=0;this.velocity=0;this.gesture=null;}
  setBounds(maximum){this.maximum=Math.max(0,maximum);this.position=clamp(this.position,0,this.maximum);if(!this.maximum)this.velocity=0;}
  setPosition(value){this.position=clamp(value,0,this.maximum);this.velocity=0;}
  begin(x,y,time){this.velocity=0;this.gesture={x,y,lastX:x,lastTime:time,dragged:false};}
  move(x,y,time){
    const g=this.gesture;if(!g)return false;
    if(!g.dragged&&Math.hypot(x-g.x,y-g.y)<LEVEL_DRAG.threshold)return false;
    g.dragged=true;const dt=Math.max(.001,time-g.lastTime),before=this.position;
    this.position=clamp(this.position+g.lastX-x,0,this.maximum);
    const sample=clamp((this.position-before)/dt,-LEVEL_DRAG.maxSpeed,LEVEL_DRAG.maxSpeed),blend=1-Math.exp(-LEVEL_DRAG.velocityFilter*dt);
    this.velocity+=(sample-this.velocity)*blend;g.lastX=x;g.lastTime=time;return true;
  }
  end(time,cancelled=false){
    const g=this.gesture;if(!g)return false;this.gesture=null;
    if(cancelled||!g.dragged)this.velocity=0;else this.velocity*=Math.exp(-LEVEL_DRAG.velocityFilter*Math.max(0,time-g.lastTime));
    return g.dragged;
  }
  stop(){this.gesture=null;this.velocity=0;}
  step(dt,reduced=false){
    if(this.gesture||!Number.isFinite(dt)||dt<=0)return;
    if(reduced){this.velocity=0;return;}
    const decay=Math.exp(-LEVEL_DRAG.friction*dt),next=this.position+this.velocity*(1-decay)/LEVEL_DRAG.friction;
    this.position=clamp(next,0,this.maximum);this.velocity*=decay;
    if(next!==this.position||Math.abs(this.velocity)<LEVEL_DRAG.stopSpeed)this.velocity=0;
  }
  snapshot(){return{x:this.position,maximum:this.maximum,velocity:this.velocity,dragging:!!this.gesture?.dragged};}
}
export function installLevelDrag(surface,viewport,enabled){
  const motion=new LevelDragMotion();let pointer=null,suppressClick=false;
  const measure=()=>motion.setBounds(viewport.scrollWidth-viewport.clientWidth),write=()=>{viewport.scrollLeft=motion.position;surface.dataset.dragging=String(!!motion.gesture?.dragged);};
  function stop(){const id=pointer;pointer=null;motion.stop();if(id!==null&&surface.hasPointerCapture(id))surface.releasePointerCapture(id);surface.dataset.dragging='false';}
  surface.addEventListener('pointerdown',e=>{
    if(!enabled()||!e.isPrimary||e.pointerType==='mouse'&&e.button!==0||pointer!==null)return;
    measure();motion.setPosition(viewport.scrollLeft);pointer=e.pointerId;suppressClick=false;motion.begin(e.clientX,e.clientY,e.timeStamp/1000);
  });
  surface.addEventListener('pointermove',e=>{
    if(pointer!==e.pointerId)return;if(!enabled()||e.pointerType==='mouse'&&e.buttons===0){stop();return;}
    if(motion.move(e.clientX,e.clientY,e.timeStamp/1000)){suppressClick=true;if(!surface.hasPointerCapture(pointer))surface.setPointerCapture(pointer);e.preventDefault();write();}
  });
  function finish(e,cancelled=false){
    if(pointer!==e.pointerId)return;const id=pointer;pointer=null;suppressClick=motion.end(e.timeStamp/1000,cancelled)||suppressClick;
    if(surface.hasPointerCapture(id))surface.releasePointerCapture(id);write();
  }
  surface.addEventListener('pointerup',e=>finish(e));surface.addEventListener('pointercancel',e=>finish(e,true));
  surface.addEventListener('lostpointercapture',e=>{if(e.target===surface&&!surface.hasPointerCapture(e.pointerId))finish(e,true);});
  window.addEventListener('pointerup',e=>finish(e));window.addEventListener('pointercancel',e=>finish(e,true));
  // Consume only the click generated by this drag. Keyboard activation remains
  // available, and a fresh pointer press immediately restores normal clicking.
  surface.addEventListener('click',e=>{if(suppressClick&&e.detail!==0){e.preventDefault();e.stopImmediatePropagation();}},true);
  surface.addEventListener('wheel',e=>{
    if(!enabled())return;measure();if(!motion.maximum)return;stop();const delta=(e.deltaX||e.deltaY)*(e.deltaMode===1?16:e.deltaMode===2?viewport.clientWidth:1);motion.setPosition(viewport.scrollLeft+delta);e.preventDefault();write();
  },{passive:false});
  viewport.addEventListener('scroll',()=>{if(!motion.gesture&&Math.abs(viewport.scrollLeft-motion.position)>1)motion.setPosition(viewport.scrollLeft);});
  window.addEventListener('blur',stop);
  return{motion,stop,reset(value=0){stop();measure();motion.setPosition(value);write();},step(dt,reduced=false){if(!enabled()){stop();return;}measure();if(Math.abs(viewport.scrollLeft-motion.position)>1)motion.setPosition(viewport.scrollLeft);motion.step(dt,reduced);write();},snapshot:()=>({...motion.snapshot(),x:viewport.scrollLeft})};
}
